$ErrorActionPreference='Stop';$n='D:\R34C953INV3\inventory.json';$p='D:\R28C953INV\inventory.json';if(-not(Test-Path $n)-or-not(Test-Path $p)){throw 'inventory absent'};$a=Get-Content $n -Raw|ConvertFrom-Json;$b=Get-Content $p -Raw|ConvertFrom-Json;$k={param($x)([string]$x.identity).ToUpper()+'|'+([string]$x.bf).Replace('/','\').ToLower()+'|'+([string]$x.df).Replace('/','\').ToLower()};$nh=@{};foreach($x in @($a.pairs)){$nh[(&$k $x)]=$x};$ph=@{};foreach($x in @($b.pairs)){$ph[(&$k $x)]=$x};$add=@($nh.Keys|Where-Object{-not$ph.ContainsKey($_)}|Sort-Object|ForEach-Object{$x=$nh[$_];[ordered]@{identity=$x.identity;bf=$x.bf;df=$x.df}});$miss=@($ph.Keys|Where-Object{-not$nh.ContainsKey($_)}|Sort-Object|ForEach-Object{$ph[$_].identity});[ordered]@{state='PASS_R34C953INV3_COMPARE';currentPairCount=$nh.Count;pinnedPairCount=$ph.Count;addedCount=$add.Count;missingCount=$miss.Count;addedRows=$add;missingIdentities=$miss;currentInventorySha256=(Get-FileHash $n).Hash;pinnedInventorySha256=(Get-FileHash $p).Hash;imageBytesRead=$false;mutationsPerformed=$false}|ConvertTo-Json -Depth 4 -Compress
